class _State extends ConsumerState<WaitingListScreen>{String query='';WaitingStatus? filter;DateTime? date;String d(DateTime x)=>'${x.year}/${x.month.toString().padLeft(2,'0')}/${x.day.toString().padLeft(2,'0')}';Future<void> save([WaitingCustomer? c])async{final value=await showDialog<WaitingCustomer>(context:context,builder:(_)=>CustomerFormDialog(initial:c));final id=ref.read(shopIdProvider).value;if(value!=null&&id!=null)await ref.read(dashboardRepositoryProvider).saveCustomer(id,value);}
@override Widget build(BuildContext context)=>SingleChildScrollView(padding:EdgeInsets.all(MediaQuery.sizeOf(context).width<600?16:32),child:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:1180),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[PageHeader(title:'キャンセル待ち',subtitle:'お客様の希望条件と対応状況を管理します。',action:FilledButton.icon(onPressed:()=>save(),icon:const Icon(Icons.person_add_alt),label:const Text('顧客を登録'))),const SizedBox(height:20),Wrap(spacing:12,runSpacing:12,children:[SizedBox(width:280,child:TextField(onChanged:(v)=>setState(()=>query=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'名前で検索'))),DropdownButton<WaitingStatus?>(value:filter,hint:const Text('すべてのステータス'),items:[const DropdownMenuItem(value:null,child:Text('すべて')), ...WaitingStatus.values.map((s)=>DropdownMenuItem(value:s,child:Text(label(s))))],onChanged:(v)=>setState(()=>filter=v)),OutlinedButton.icon(onPressed:()async{final v=await showDatePicker(context:context,firstDate:DateTime(2020),lastDate:DateTime(2035),initialDate:date??DateTime.now());if(v!=null)setState(()=>date=v);},icon:const Icon(Icons.filter_alt_outlined),label:Text(date==null?'日付':'${d(date!)}（解除）'),onLongPress:()=>setState(()=>date=null))]),const SizedBox(height:20),AsyncContent(value:ref.watch(waitingCustomersProvider),builder:(all){final list=all.where((c)=>c.name.contains(query)&&(filter==null||c.status==filter)&&(date==null||(d(c.preferredDate)==d(date!)))).toList();if(list.isEmpty)return const Center(child:Padding(padding:EdgeInsets.all(48),child:Text('条件に一致する顧客はいません。')));return Column(children:list.map((c)=>Padding(padding:const EdgeInsets.only(bottom:10),child:Card(child:ListTile(contentPadding:const EdgeInsets.all(16),leading:CircleAvatar(child:Text(c.name.characters.first)),title:Wrap(spacing:8,children:[Text(c.name,style:const TextStyle(fontWeight:FontWeight.bold)),StatusBadge(label(c.status),color:color(c.status)),StatusBadge(c.lineLinked?'LINE連携済み':'LINE未連携',color:c.lineLinked?Colors.green:Colors.grey)]),subtitle:Padding(padding:const EdgeInsets.only(top:8),child:Text('${d(c.preferredDate)} ${c.preferredStartTime}〜${c.preferredEndTime} ・ ${c.menuName}${c.phone.isEmpty?'':' ・ ${c.phone}'}')),trailing:PopupMenuButton<String>(onSelected:(v)async{if(v=='edit')save(c);if(v=='delete'){final yes=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('顧客を削除しますか？'),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('キャンセル')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('削除'))]));final id=ref.read(shopIdProvider).value;if(yes==true&&id!=null)await ref.read(dashboardRepositoryProvider).deleteCustomer(id,c.id);}},itemBuilder:(_)=>const [PopupMenuItem(value:'edit',child:Text('編集')),PopupMenuItem(value:'delete',child:Text('削除'))]))))).toList());})]))));}
